// Author: MiYu. Exercise the source Orc finale's Soul Gem and rescued hero sequence.
#include "session.h"
#include "setup.h"
#include <iostream>

using namespace war3;
int wmain(int argc,wchar_t** argv){try{
    if(argc!=4)throw std::runtime_error("Usage: war3_orc_soul_campaign_tests <data-root> <Orc08.w3m> <new-absolute-user-dir>");fs::path user(argv[3]);if(!user.is_absolute() || !fs::create_directory(user) || !SetEnvironmentVariableW(L"MEGINE_WAR3_USER_DIR",user.c_str()))throw std::runtime_error("Cannot create isolated user directory");
    Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;MapStrings strings;if(auto wts=archives.readCandidates({"war3map.wts"},ArchiveScope::Map))strings=mapStrings(wts->bytes);ScriptSession s(jass::Module::compile(jass::Program::read(archives)),info,std::move(strings));s.campaignContext(false,1);s.attachWorld(std::move(world));s.audioSimulationClock();s.audioMuted(true);s.configure();PlayerSetup setup(info,s.config());s.applySetup(setup);s.startMain();for(int i=0;i<560;++i)s.advance(.25);
    auto require=[](bool ok,const char* message){if(!ok)throw std::runtime_error(message);};auto& vm=s.runtime();auto hero=vm.global("udg_Thrall"),grom=vm.global("udg_Grom");require(s.units().contains(hero.bits) && s.units().contains(grom.bits),"Campaign heroes missing");auto h=s.units().at(hero.bits),g=s.units().at(grom.bits);for(auto& [id,u]:s.units())if(id!=hero.bits)u->paused=true;g->paused=false;h->paused=false;h->mana=h->maxMana=jass::Real::fromInteger(1000);vm.invoke("SetUnitInvulnerable",std::array{hero,vm.boolean(true)});vm.invoke("SetUnitInvulnerable",std::array{grom,vm.boolean(false)});vm.invoke("SetPlayerAlliance",std::array{vm.handle("player",0x100000),vm.handle("player",0x100000+g->owner),vm.handle("alliancetype",0),vm.boolean(false)});auto real=[&](int n){return vm.real(jass::Real::fromInteger(n));};vm.invoke("SetUnitPosition",std::array{hero,real(0),real(0)});vm.invoke("SetUnitPosition",std::array{grom,real(100),real(0)});vm.invoke("FogEnable",std::array{vm.boolean(false)});vm.invoke("FogMaskEnable",std::array{vm.boolean(false)});
    std::uint32_t gem=0;for(auto id:h->inventory)if(id && s.items().contains(id) && s.items().at(id)->type==ObjectData::code("gsou"))gem=id;require(gem && s.useItem(hero.bits,gem,grom.bits),"Original Soul Gem use failed");for(int i=0;i<16;++i)s.advance(.25);auto marker=vm.global("udg_SoulItemVar").bits;unsigned count=0;for(auto id:h->inventory)if(id && s.items().contains(id) && s.items().at(id)->type==ObjectData::code("soul")){++count;require(id==marker,"Soul item did not come from map script");}require(count==1 && g->soulCaptor==hero.bits && g->abilities.contains(ObjectData::code("Asou")),"Capture or script-owned soul item differs");
    auto rect=vm.global("gg_rct_Jaina_COP");vm.invoke("SetUnitPosition",std::array{hero,vm.invoke("GetRectCenterX",std::array{rect}),vm.invoke("GetRectCenterY",std::array{rect})});for(int i=0;i<2000 && s.exitRequest()==SessionExit::None;++i)s.advance(.25);auto owner=s.localPlayer().value_or(0);auto freed=vm.global("udg_Grom");require(s.exitRequest()==SessionExit::Return && s.results()[owner] && *s.results()[owner]==0,"Campaign victory not reached");require(!g->soulCaptor && !g->abilities.contains(ObjectData::code("Asou")) && s.units().contains(freed.bits) && s.units().at(freed.bits)->type==ObjectData::code("Ogrh"),"Cinematic did not release and restore Grom");require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS Orc08 Soul Gem capture, release and victory\nRESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
